"use client";

import { motion, useReducedMotion, type Transition } from "motion/react";
import {
  type ComponentPropsWithoutRef,
  type FocusEvent,
  type PointerEvent,
  type ReactNode,
  useEffect,
  useId,
  useRef,
  useState,
} from "react";

import { cn } from "@/lib/utils";

/** One action in the bar. The label names the button even while only the icon shows. */
export interface ExpandableAction {
  id: string;
  label: string;
  icon: ReactNode;
  onSelect: () => void;
  disabled?: boolean;
}

/**
 * Props for a row of icon actions that grow labels on hover or focus. The bar
 * owns its pointer and focus handlers, so the props leave them out rather than
 * drop a caller's handler silently.
 */
export type ExpandableActionBarProps = Omit<
  ComponentPropsWithoutRef<"div">,
  "children" | "onPointerEnter" | "onPointerLeave" | "onFocus" | "onBlur"
> & {
  /** Names the row for screen readers, for example "Editor actions". */
  label: string;
  actions: ExpandableAction[];
};

// Damping 41 is 2 × √420, rounded up: critically damped, so the labels open without overshoot.
const WIDEN: Transition = { type: "spring", stiffness: 420, damping: 41, mass: 1 };
// Reduced motion snaps the width and keeps the fade, because a fade is not motion.
const SNAP_AND_FADE: Transition = { width: { duration: 0 }, opacity: { duration: 0.15 } };
const INSTANT: Transition = { duration: 0 };
// A short grace period stops the bar from closing while the pointer crosses a gap.
const CLOSE_DELAY_MS = 120;

/**
 * Shows a row of icon actions that expand into labelled actions when a pointer
 * rests on the row or focus enters it. On touch, where nothing hovers, the
 * first tap opens the labels and the next tap acts.
 */
export function ExpandableActionBar({ label, actions, className, ...divProps }: ExpandableActionBarProps) {
  const [isExpanded, setIsExpanded] = useState(false);
  const [highlighted, setHighlighted] = useState<string | null>(null);
  const reduceMotion = useReducedMotion();
  // Each bar needs its own layout id, or two bars on one page would share one highlight.
  const layoutId = useId();
  const rootRef = useRef<HTMLDivElement>(null);
  const closeTimer = useRef<number | null>(null);
  // The press in progress, and whether the bar was open when it began. A
  // browser that focuses a button on contact opens the bar mid-tap, so the
  // click must read the state from the start of the press.
  const press = useRef<{ type: string; wasExpanded: boolean } | null>(null);

  const cancelClose = () => {
    if (closeTimer.current !== null) window.clearTimeout(closeTimer.current);
    closeTimer.current = null;
  };

  const setExpanded = (next: boolean) => {
    cancelClose();
    setIsExpanded(next);
    if (!next) setHighlighted(null);
  };

  const closeSoon = () => {
    cancelClose();
    closeTimer.current = window.setTimeout(() => setExpanded(false), CLOSE_DELAY_MS);
  };

  useEffect(() => cancelClose, []);

  // A bar a finger opened has no pointer to leave it, so a tap outside closes it.
  useEffect(() => {
    if (!isExpanded) return;
    const onPointerDown = (event: globalThis.PointerEvent) => {
      if (event.target instanceof Node && rootRef.current?.contains(event.target)) return;
      if (event.pointerType === "mouse") return;
      setIsExpanded(false);
      setHighlighted(null);
    };
    document.addEventListener("pointerdown", onPointerDown);
    return () => document.removeEventListener("pointerdown", onPointerDown);
  }, [isExpanded]);

  const onPointerEnter = (event: PointerEvent<HTMLDivElement>) => {
    if (event.pointerType === "mouse") setExpanded(true);
  };

  const onPointerLeave = (event: PointerEvent<HTMLDivElement>) => {
    if (event.pointerType !== "mouse") return;
    setHighlighted(null);
    // A mouse click focuses the button too, but only keyboard focus should hold the bar open.
    if (!rootRef.current?.querySelector(":focus-visible")) closeSoon();
  };

  const onBlur = (event: FocusEvent<HTMLDivElement>) => {
    if (event.relatedTarget instanceof Node && event.currentTarget.contains(event.relatedTarget)) return;
    if (!rootRef.current?.matches(":hover")) closeSoon();
  };

  const select = (action: ExpandableAction) => {
    const touchFirst = press.current !== null && press.current.type !== "mouse" && !press.current.wasExpanded;
    press.current = null;
    if (action.disabled) return;
    // Nothing shows a finger the labels before it lands, so the first tap only opens them.
    if (touchFirst) {
      setExpanded(true);
      setHighlighted(action.id);
      return;
    }
    action.onSelect();
  };

  return (
    <div
      {...divProps}
      ref={rootRef}
      role="group"
      aria-label={label}
      data-expanded={isExpanded || undefined}
      onPointerEnter={onPointerEnter}
      onPointerLeave={onPointerLeave}
      onFocus={() => setExpanded(true)}
      onBlur={onBlur}
      // On a narrow screen the open row scrolls sideways. Its scrollbar is
      // hidden, because a bar inside a pill reads as a broken border.
      className={cn(
        "inline-flex max-w-full items-center gap-1 overflow-x-auto rounded-full border border-border bg-card p-1 shadow-sm [scrollbar-width:none]",
        className,
      )}
    >
      {actions.map((action) => (
        <button
          key={action.id}
          type="button"
          aria-disabled={action.disabled || undefined}
          onPointerDown={(event) => {
            press.current = { type: event.pointerType, wasExpanded: isExpanded };
          }}
          onPointerEnter={(event) => {
            if (event.pointerType === "mouse") setHighlighted(action.id);
          }}
          onFocus={() => setHighlighted(action.id)}
          onClick={() => select(action)}
          className={cn(
            "relative inline-flex min-h-11 min-w-11 shrink-0 cursor-pointer touch-manipulation items-center justify-center rounded-full px-3 text-sm font-medium outline-none sm:min-h-9 sm:min-w-9 sm:px-2.5",
            "focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring",
            "aria-disabled:cursor-not-allowed aria-disabled:opacity-50",
            highlighted === action.id ? "text-foreground" : "text-muted-foreground",
          )}
        >
          {highlighted === action.id ? (
            <motion.span
              layoutId={layoutId}
              aria-hidden="true"
              transition={reduceMotion ? INSTANT : WIDEN}
              className="absolute inset-0 rounded-full bg-muted"
            />
          ) : null}
          <span className="relative inline-flex size-4 items-center justify-center" aria-hidden="true">
            {action.icon}
          </span>
          {/* The label stays in the accessible name while it is folded, so the button is never nameless. */}
          <motion.span
            initial={false}
            animate={isExpanded ? { width: "auto", opacity: 1 } : { width: 0, opacity: 0 }}
            transition={reduceMotion ? SNAP_AND_FADE : WIDEN}
            className="relative overflow-hidden whitespace-nowrap"
          >
            <span className="inline-block pl-2">{action.label}</span>
          </motion.span>
        </button>
      ))}
    </div>
  );
}
